// Helper: get display label for a build number
function getBuildLabel(build) {
    if (!build || build === '-') return '';
    const b = String(build).trim();
    const meta = SALESFORCE_BUILDS[b];
    if (meta) return meta.name + ' (Build ' + b + ')';
    return 'Build ' + b;
}

