        designLead: "",
        qualityLead: "",
        v2momMethod: "",
        version: "service",
        details: {
            overview: "This epic migrates Field Service Core to Off-Core authentication flow from legacy opaque C2C session tokens to a modernized mTLS and CASC-based architecture.",
            keyFeatures: [
                "Core to Off-Core (inbound): mTLS via SFAP on port 9443, replacing C2C token in headers",
                "Off-Core to Core (callback): CASC headers (x-sfdc-core-tenant-id, x-sfdc-app-context) replacing Authorization: Bearer token",
                "Async flows: tenant key propagated on SessionKey via SQS, eliminating Vault token store/read",
                "Navigation/Matrix: eliminate Poor Man's Auth dummy Core validation call",
                "Hybrid dual-port phase: port 9443 (mTLS) + port 443 (legacy) coexist during migration"
            ],
            impact: ""
        },
